package com.bankbis;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("bank-bis")
public interface BankBisConfig extends Config
{

	enum HeaderDps
	{
		SETTINGS("Optimizer settings"),
		BASE("Base"),
		PRAYER("Prayer"),
		POTTED("Pray + pots"),
		;

		private final String label;

		HeaderDps(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigItem(
		keyName = "headerDps",
		name = "Title DPS",
		description = "Which DPS number each loadout's title shows: the value the optimizer "
			+ "maximized under your panel settings, or a fixed scenario (base / prayed / potted)"
	)
	default HeaderDps headerDps()
	{
		return HeaderDps.SETTINGS;
	}

	@ConfigItem(
		keyName = "includeGroupStorage",
		name = "Include group storage",
		description = "Count items in group ironman storage as owned when recommending gear"
	)
	default boolean includeGroupStorage()
	{
		return true;
	}

	@ConfigItem(
		keyName = "forceSlayerTask",
		name = "On slayer task",
		description = "Apply the slayer helmet / black mask boost even for monsters not auto-detected as your task"
	)
	default boolean forceSlayerTask()
	{
		return false;
	}

	@ConfigItem(
		keyName = "sharePartyBanks",
		name = "Share banks with party",
		description = "Share your equippable items (ids and quantities only) with your RuneLite party via the "
			+ "RuneLite party service, and include party members' shared items in recommendations. "
			+ "Items a party member owns are marked '(party)'."
	)
	default boolean sharePartyBanks()
	{
		return false;
	}

}

package com.bankbis;

import com.bankbis.bank.OwnedItemsService;
import com.bankbis.data.WikiDataService;
import com.bankbis.party.OwnedItemsUpdate;
import com.bankbis.party.PartyItemsService;
import com.bankbis.ui.BankBisPanel;
import com.bankbis.ui.BankFilterService;
import com.bankbis.ui.BankHighlightOverlay;
import com.bankbis.ui.TargetPickerState;
import com.duckblade.osrs.dpscalc.calc.DpsComputeModule;
import com.google.inject.Binder;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.inject.Provider;
import lombok.extern.slf4j.Slf4j;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.PostMenuSort;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.party.WSClient;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Banked BiS",
	description = "Recommends the best gear setup you own for a chosen activity, based on your bank and group storage",
	tags = {"gear", "bis", "dps", "bank", "equipment", "loadout"}
)
// makes the core Bank Tags plugin's bindings (BankTagsService, TagManager)
// available to this plugin's injector for the bank filter integration
@PluginDependency(BankTagsPlugin.class)
public class BankBisPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private EventBus eventBus;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OwnedItemsService ownedItemsService;

	@Inject
	private WikiDataService wikiDataService;

	@Inject
	private PartyItemsService partyItemsService;

	@Inject
	private WSClient wsClient;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private BankHighlightOverlay bankHighlightOverlay;

	@Inject
	private TargetPickerState targetPickerState;

	@Inject
	private BankFilterService bankFilterService;

	// injected lazily: the panel must be constructed in startUp(), after the
	// client has installed its look-and-feel, or its components render unstyled
	@Inject
	private Provider<BankBisPanel> panelProvider;

	private BankBisPanel panel;
	private NavigationButton navButton;

	/**
	 * While the picker is armed, put a "Select target" entry on top of the
	 * menu for the hovered NPC (wiki-lookup style): the top-left hover text
	 * shows the action, left-click runs it, and nothing goes to the server.
	 * PostMenuSort fires after the client has built and sorted the frame's
	 * menu - entries added earlier (e.g. during ClientTick) get wiped.
	 */
	@Subscribe
	public void onPostMenuSort(PostMenuSort e)
	{
		if (!targetPickerState.isArmed() || client.isMenuOpen())
		{
			return;
		}
		MenuEntry[] entries = client.getMenu().getMenuEntries();
		for (int i = entries.length - 1; i >= 0; i--)
		{
			NPC npc = entries[i].getNpc();
			if (npc != null)
			{
				client.getMenu().createMenuEntry(-1)
					.setOption("Select target")
					.setTarget(entries[i].getTarget())
					.setType(MenuAction.RUNELITE)
					.onClick(me -> pickNpc(npc));
				return;
			}
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked e)
	{
		if (!targetPickerState.isArmed())
		{
			return;
		}
		NPC npc = e.getMenuEntry().getNpc();
		if (npc == null)
		{
			return; // not a monster click; stay armed so a misclick doesn't cancel
		}
		e.consume(); // don't attack/interact - this click was a selection
		pickNpc(npc);
	}

	private void pickNpc(NPC npc)
	{
		if (panel == null)
		{
			return;
		}
		targetPickerState.setArmed(false);
		int npcId = npc.getId();
		String npcName = npc.getName();
		SwingUtilities.invokeLater(() -> panel.setPickedTarget(npcId, npcName));
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed e)
	{
		if (e.getGroupId() == InterfaceID.BANKMAIN && panel != null)
		{
			// the highlight is a transient aid; drop it when the bank closes
			SwingUtilities.invokeLater(panel::clearBankHighlight);
		}
	}

	@Override
	public void configure(Binder binder)
	{
		binder.install(new DpsComputeModule());
	}

	@Override
	protected void startUp() throws Exception
	{
		eventBus.register(ownedItemsService);
		eventBus.register(partyItemsService);
		wsClient.registerMessage(OwnedItemsUpdate.class);
		overlayManager.add(bankHighlightOverlay);
		wikiDataService.load()
			.exceptionally(e ->
			{
				log.warn("Failed to load wiki data", e);
				return null;
			});

		panel = panelProvider.get();
		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "panel_icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Banked BiS")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
	}

	@Override
	protected void shutDown() throws Exception
	{
		eventBus.unregister(ownedItemsService);
		eventBus.unregister(partyItemsService);
		wsClient.unregisterMessage(OwnedItemsUpdate.class);
		overlayManager.remove(bankHighlightOverlay);
		targetPickerState.setArmed(false);
		bankFilterService.clear();
		ownedItemsService.flush();
		wikiDataService.shutdown();
		clientToolbar.removeNavigation(navButton);
	}

	@Provides
	BankBisConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BankBisConfig.class);
	}
}

package com.bankbis;

import com.bankbis.bank.OwnedItemsService;
import com.bankbis.content.RaidScaling;
import com.bankbis.content.Target;
import com.bankbis.data.NpcStats;
import com.bankbis.data.WikiDataService;
import com.bankbis.party.PartyItemsService;
import com.bankbis.optimizer.Loadout;
import com.bankbis.optimizer.LoadoutOptimizer;
import com.bankbis.optimizer.OptimizeRequest;
import com.bankbis.optimizer.PotionBoost;
import com.bankbis.optimizer.PrayerAssumption;
import com.bankbis.optimizer.PrayerUnlocks;
import com.duckblade.osrs.dpscalc.calc.model.ItemStats;
import com.duckblade.osrs.dpscalc.calc.model.Prayer;
import com.duckblade.osrs.dpscalc.calc.model.Skills;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;

/**
 * Glue between the live client (skills, owned items) and the optimizer.
 */
@Singleton
@RequiredArgsConstructor(onConstructor = @__(@Inject))
public class RecommendationService
{

	private final Client client;
	private final ClientThread clientThread;
	private final OwnedItemsService ownedItemsService;
	private final WikiDataService wikiDataService;
	private final PartyItemsService partyItemsService;
	private final LoadoutOptimizer optimizer;
	private final ScheduledExecutorService executor;
	private final BankBisConfig config;

	@Value
	public static class Result
	{
		List<Loadout> loadouts;
		List<String> warnings;

		/**
		 * Item ids only available via a party member's shared bank.
		 */
		Set<Integer> partyItemIds;

		/**
		 * Item ids that live only in group storage (not bank/inventory/worn),
		 * so the player has to fetch them before use.
		 */
		Set<Integer> groupStorageItemIds;
	}

	/**
	 * Skills and prayer unlocks captured together on the client thread.
	 * Null when not logged in.
	 */
	@Value
	private static class ClientSnapshot
	{
		Skills skills;
		PrayerUnlocks prayerUnlocks;
	}

	public CompletableFuture<Result> recommend(Target target, PotionBoost potionBoost, PrayerAssumption prayerAssumption)
	{
		CompletableFuture<ClientSnapshot> snapshotFuture = new CompletableFuture<>();
		clientThread.invoke(() ->
		{
			try
			{
				snapshotFuture.complete(snapshotClient());
			}
			catch (Exception e)
			{
				snapshotFuture.completeExceptionally(e);
			}
		});
		return snapshotFuture
			.orTimeout(15, TimeUnit.SECONDS) // never leave the panel wedged on "Computing..."
			.thenApplyAsync(snapshot -> compute(
				target,
				snapshot == null ? null : applyBoosts(snapshot.getSkills(), potionBoost),
				snapshot == null ? PrayerUnlocks.ALL : snapshot.getPrayerUnlocks(),
				potionBoost,
				prayerAssumption), executor);
	}

	private static Skills applyBoosts(Skills skills, PotionBoost potionBoost)
	{
		if (skills == null)
		{
			return null;
		}
		Map<Skill, Integer> boosts = potionBoost.boostsFor(skills.getLevels());
		if (boosts == null)
		{
			return skills; // CURRENT: keep live boosts
		}
		return Skills.builder().levels(skills.getLevels()).boosts(boosts).build();
	}

	private ClientSnapshot snapshotClient()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return null;
		}

		Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
		Map<Skill, Integer> boosts = new EnumMap<>(Skill.class);
		for (Skill s : Skill.values())
		{
			int real = client.getRealSkillLevel(s);
			levels.put(s, real);
			boosts.put(s, client.getBoostedSkillLevel(s) - real);
		}
		Skills skills = Skills.builder().levels(levels).boosts(boosts).build();

		// Knight Waves completion (state 8) gates both Piety and Chivalry,
		// and can only be done after King's Ransom
		PrayerUnlocks unlocks = new PrayerUnlocks(
			client.getVarbitValue(VarbitID.KR_KNIGHTWAVES_STATE) >= 8,
			client.getVarbitValue(VarbitID.PRAYER_RIGOUR_UNLOCKED) == 1,
			client.getVarbitValue(VarbitID.PRAYER_AUGURY_UNLOCKED) == 1);

		return new ClientSnapshot(skills, unlocks);
	}

	private Result compute(Target target, Skills skills, PrayerUnlocks prayerUnlocks, PotionBoost potionBoost, PrayerAssumption prayerAssumption)
	{
		List<String> warnings = new ArrayList<>();

		if (skills == null)
		{
			return new Result(Collections.emptyList(), List.of("Log in to get recommendations."), Collections.emptySet(), Collections.emptySet());
		}

		Map<Integer, ItemStats> wikiItems = wikiDataService.getItemStatsById();
		if (wikiItems.isEmpty())
		{
			return new Result(Collections.emptyList(), List.of("Equipment data is still loading; try again shortly."), Collections.emptySet(), Collections.emptySet());
		}

		NpcStats npcStats = wikiDataService.getNpcStatsById().get(target.getNpcId());
		if (npcStats == null)
		{
			return new Result(Collections.emptyList(), List.of("No monster data for " + target.getLabel() + "."), Collections.emptySet(), Collections.emptySet());
		}
		npcStats = RaidScaling.scale(npcStats, target);

		if (!ownedItemsService.hasBankSnapshot())
		{
			warnings.add("Bank not scanned yet - open your bank once so all your items are known.");
		}

		Map<Integer, Integer> ownedQuantities = config.includeGroupStorage()
			? ownedItemsService.getOwnedQuantities()
			: ownedItemsService.getOwnedQuantitiesExcluding(OwnedItemsService.Source.GROUP_STORAGE);

		Set<Integer> partyItemIds = new HashSet<>();
		if (config.sharePartyBanks())
		{
			partyItemsService.getPartyQuantities().forEach((id, qty) ->
			{
				if (!ownedQuantities.containsKey(id))
				{
					partyItemIds.add(id);
				}
				ownedQuantities.merge(id, qty, Integer::sum);
			});
		}

		List<ItemStats> ownedEquipment = new ArrayList<>();
		for (Integer itemId : ownedQuantities.keySet())
		{
			ItemStats stats = wikiItems.get(itemId);
			if (stats != null)
			{
				ownedEquipment.add(stats);
			}
		}

		if (ownedEquipment.isEmpty())
		{
			warnings.add("No equippable items found yet.");
			return new Result(Collections.emptyList(), warnings, Collections.emptySet(), Collections.emptySet());
		}

		OptimizeRequest request = OptimizeRequest.builder()
			.ownedEquipment(ownedEquipment)
			.playerSkills(skills)
			.target(npcStats)
			.onSlayerTask(target.isOnSlayerTask())
			.raidPartySize(target.getRaidPartySize())
			.prayerAssumption(prayerAssumption)
			.prayerUnlocks(prayerUnlocks)
			.build();

		Set<Integer> groupStorageItemIds = config.includeGroupStorage()
			? ownedItemsService.getGroupOnlyItemIds()
			: Collections.emptySet();

		List<Loadout> loadouts = new ArrayList<>();
		for (Loadout loadout : optimizer.optimize(request))
		{
			loadouts.add(withBreakdown(loadout, request, potionBoost, prayerAssumption));
		}
		return new Result(loadouts, warnings, partyItemIds, groupStorageItemIds);
	}

	/**
	 * Re-evaluates the chosen gear under fixed scenarios so the panel can
	 * show what potting/praying is worth: base (nothing), prayed (prayers
	 * only), potted (prayers + potion). "Potted" uses the selected potion,
	 * or a super set when the selection is CURRENT/NONE, so the line is
	 * meaningful even when optimizing from live unpotted stats.
	 */
	private Loadout withBreakdown(Loadout loadout, OptimizeRequest request, PotionBoost potionBoost, PrayerAssumption prayerAssumption)
	{
		Skills skills = request.getPlayerSkills();
		PotionBoost pottedBoost = potionBoost == PotionBoost.CURRENT || potionBoost == PotionBoost.NONE
			? PotionBoost.SUPER_SET
			: potionBoost;

		Skills unboosted = Skills.builder().levels(skills.getLevels()).boosts(PotionBoost.NONE.boostsFor(skills.getLevels())).build();
		Skills potted = Skills.builder().levels(skills.getLevels()).boosts(pottedBoost.boostsFor(skills.getLevels())).build();

		Integer prayerLevel = skills.getLevels().get(Skill.PRAYER);
		Set<Prayer> prayers = prayerAssumption.prayersFor(loadout.getCombatClass(),
			prayerLevel == null ? 0 : prayerLevel, request.getPrayerUnlocks());

		double base = optimizer.evaluateLoadout(request.toBuilder().playerSkills(unboosted).build(), loadout, Collections.emptySet());
		double prayed = optimizer.evaluateLoadout(request.toBuilder().playerSkills(unboosted).build(), loadout, prayers);
		double pottedDps = optimizer.evaluateLoadout(request.toBuilder().playerSkills(potted).build(), loadout, prayers);

		if (base < 0 || prayed < 0 || pottedDps < 0)
		{
			return loadout;
		}
		return loadout.toBuilder().breakdown(new Loadout.DpsBreakdown(base, prayed, pottedDps)).build();
	}

}

package com.bankbis.bank;

/**
 * Posted on the event bus whenever a tracked item container updates.
 */
public class OwnedItemsChanged
{
}

package com.bankbis.bank;

import com.bankbis.data.PluginData;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.File;
import java.io.IOException;
import java.io.Reader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.IntPredicate;
import java.util.function.IntUnaryOperator;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;

/**
 * Tracks every item the player owns across bank, group storage, inventory,
 * and worn equipment. Containers are snapshotted whenever the client updates
 * them and persisted per-account, so a full picture is available even after
 * the bank is closed or the client restarted (bank/group storage require
 * having been opened at least once).
 *
 * <p>Threading: event handlers run on the client thread; disk IO runs on the
 * shared executor. All mutable state ({@code owned}, {@code loadedAccount},
 * {@code pendingSave}) is guarded by this object's monitor. Async tasks
 * re-validate the account they captured against {@code loadedAccount} before
 * touching state or disk, so a quick relog/world-hop can never write one
 * account's items into another account's file.
 */
@Slf4j
@Singleton
public class OwnedItemsService
{

	public enum Source
	{
		BANK,
		GROUP_STORAGE,
		INVENTORY,
		EQUIPMENT,
	}

	private static final Map<Integer, Source> CONTAINER_SOURCES = buildContainerSources();

	private static final Type PERSIST_TYPE = new TypeToken<EnumMap<Source, HashMap<Integer, Integer>>>()
	{
	}.getType();

	private static final long SAVE_DEBOUNCE_MS = 5_000;

	private final Client client;
	private final ItemManager itemManager;
	private final Gson gson;
	private final ScheduledExecutorService executor;
	private final EventBus eventBus;
	private final File dataDir;

	private final Map<Source, Map<Integer, Integer>> owned = new EnumMap<>(Source.class);
	private long loadedAccount = -1;
	private ScheduledFuture<?> pendingSave;

	@Inject
	public OwnedItemsService(Client client, ItemManager itemManager, Gson gson, ScheduledExecutorService executor, EventBus eventBus)
	{
		this(client, itemManager, gson, executor, eventBus, PluginData.DIR);
	}

	OwnedItemsService(Client client, ItemManager itemManager, Gson gson, ScheduledExecutorService executor, EventBus eventBus, File dataDir)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.gson = gson;
		this.executor = executor;
		this.eventBus = eventBus;
		this.dataDir = dataDir;
	}

	private static Map<Integer, Source> buildContainerSources()
	{
		Map<Integer, Source> sources = new HashMap<>();
		sources.put(InventoryID.BANK, Source.BANK);
		sources.put(InventoryID.INV_GROUP_TEMP, Source.GROUP_STORAGE);
		sources.put(InventoryID.INV, Source.INVENTORY);
		// while the group storage UI is open, the player's inventory is
		// represented by this temp container; without it, deposits leave
		// stale copies recorded under INVENTORY
		sources.put(InventoryID.INV_PLAYER_TEMP, Source.INVENTORY);
		sources.put(InventoryID.WORN, Source.EQUIPMENT);
		return Collections.unmodifiableMap(sources);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		if (e.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		long account = client.getAccountHash();
		synchronized (this)
		{
			if (account == -1 || account == loadedAccount)
			{
				return;
			}
			cancelPendingSave();
			owned.clear();
			loadedAccount = account;
		}
		executor.execute(() -> loadFromDisk(account));
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged e)
	{
		Source source = CONTAINER_SOURCES.get(e.getContainerId());
		if (source == null)
		{
			return;
		}

		// runs on the client thread, where item composition lookups are safe
		updateSource(source, e.getItemContainer().getItems(), itemManager::canonicalize,
			id -> itemManager.getItemComposition(id).getPlaceholderTemplateId() != -1);

		long account = client.getAccountHash();
		if (account != -1)
		{
			scheduleSave(account);
		}
		eventBus.post(new OwnedItemsChanged());
	}

	/**
	 * Inventory changes fire constantly during play; coalesce writes so at
	 * most one save happens per debounce window.
	 */
	private synchronized void scheduleSave(long account)
	{
		if (pendingSave != null && !pendingSave.isDone())
		{
			return;
		}
		pendingSave = executor.schedule(() -> saveIfCurrent(account), SAVE_DEBOUNCE_MS, TimeUnit.MILLISECONDS);
	}

	private synchronized void cancelPendingSave()
	{
		if (pendingSave != null)
		{
			pendingSave.cancel(false);
			pendingSave = null;
		}
	}

	/**
	 * Persists immediately, cancelling any pending debounced save. Call on
	 * plugin shutdown.
	 */
	public void flush()
	{
		long account;
		synchronized (this)
		{
			cancelPendingSave();
			account = loadedAccount;
		}
		if (account != -1)
		{
			executor.execute(() -> saveIfCurrent(account));
		}
	}

	/**
	 * Replaces one source's contents. Noted items resolve to their canonical
	 * id; empty slots, zero quantities, and bank placeholders are dropped.
	 * Placeholders must be detected via item composition - they can carry a
	 * nonzero quantity in the container, and canonicalize would resolve them
	 * to the real item as if it were owned.
	 */
	void updateSource(Source source, Item[] items, IntUnaryOperator canonicalize, IntPredicate isPlaceholder)
	{
		Map<Integer, Integer> quantities = new HashMap<>();
		for (Item item : items)
		{
			if (item == null || item.getId() <= 0 || item.getQuantity() <= 0 || isPlaceholder.test(item.getId()))
			{
				continue;
			}
			int id = canonicalize.applyAsInt(item.getId());
			quantities.merge(id, item.getQuantity(), Integer::sum);
		}

		synchronized (this)
		{
			owned.put(source, quantities);
		}
	}

	/**
	 * All owned items merged across sources, quantities summed.
	 */
	public Map<Integer, Integer> getOwnedQuantities()
	{
		return getOwnedQuantitiesExcluding(null);
	}

	public synchronized Map<Integer, Integer> getOwnedQuantitiesExcluding(Source excluded)
	{
		Map<Integer, Integer> merged = new HashMap<>();
		owned.forEach((source, items) ->
		{
			if (source != excluded)
			{
				items.forEach((id, qty) -> merged.merge(id, qty, Integer::sum));
			}
		});
		return merged;
	}

	/**
	 * Item ids present in group storage and nowhere else the player can
	 * reach directly (bank/inventory/equipment) - i.e. gear that must be
	 * fetched from group storage to actually wear.
	 */
	public synchronized Set<Integer> getGroupOnlyItemIds()
	{
		Map<Integer, Integer> group = owned.get(Source.GROUP_STORAGE);
		if (group == null || group.isEmpty())
		{
			return Collections.emptySet();
		}
		Set<Integer> ids = new HashSet<>(group.keySet());
		owned.forEach((source, items) ->
		{
			if (source != Source.GROUP_STORAGE)
			{
				ids.removeAll(items.keySet());
			}
		});
		return ids;
	}

	/**
	 * Canonical ids of currently worn equipment, for marking recommended
	 * pieces the player already has on.
	 */
	public synchronized Set<Integer> getWornItemIds()
	{
		Map<Integer, Integer> worn = owned.get(Source.EQUIPMENT);
		return worn == null ? Collections.emptySet() : new HashSet<>(worn.keySet());
	}

	public synchronized boolean hasBankSnapshot()
	{
		return owned.containsKey(Source.BANK);
	}

	/**
	 * @return a deep copy of current state, or null if the given account is
	 * no longer the loaded one (stale async task).
	 */
	private synchronized Map<Source, Map<Integer, Integer>> snapshotIfCurrent(long account)
	{
		if (account != loadedAccount)
		{
			return null;
		}
		Map<Source, Map<Integer, Integer>> copy = new EnumMap<>(Source.class);
		owned.forEach((k, v) -> copy.put(k, new HashMap<>(v)));
		return copy;
	}

	private File fileFor(long account)
	{
		return new File(dataDir, "owned-" + Long.toHexString(account) + ".json");
	}

	private void loadFromDisk(long account)
	{
		File file = fileFor(account);
		if (!file.exists())
		{
			return;
		}

		Map<Source, Map<Integer, Integer>> persisted;
		try (Reader reader = Files.newBufferedReader(file.toPath(), StandardCharsets.UTF_8))
		{
			persisted = gson.fromJson(reader, PERSIST_TYPE);
		}
		catch (Exception e)
		{
			log.warn("Failed to load owned-items snapshot", e);
			return;
		}
		if (persisted == null)
		{
			return;
		}

		synchronized (this)
		{
			if (account != loadedAccount)
			{
				return; // player already switched accounts; drop the stale load
			}
			// live container updates win over persisted state
			persisted.forEach(owned::putIfAbsent);
		}
		log.debug("Loaded owned-items snapshot for account {}", Long.toHexString(account));
	}

	private void saveIfCurrent(long account)
	{
		Map<Source, Map<Integer, Integer>> snapshot = snapshotIfCurrent(account);
		if (snapshot == null)
		{
			return;
		}
		try
		{
			PluginData.writeAtomically(fileFor(account), gson.toJson(snapshot, PERSIST_TYPE).getBytes(StandardCharsets.UTF_8));
		}
		catch (IOException e)
		{
			log.warn("Failed to save owned-items snapshot", e);
		}
	}

}

