{

	int npcId;
	String label;

	@Builder.Default
	boolean onSlayerTask = false;

	@Builder.Default
	int raidPartySize = 1;

	@Builder.Default
	RaidType raid = RaidType.NONE;

	@Builder.Default
	boolean coxChallengeMode = false;

	/**
	 * Stored for future time-to-kill work; invocation level scales monster
	 * HP only, so it does not affect gear ranking.
