package com.bankbis.data;

import java.io.File;
import java.io.IOException;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import net.runelite.client.RuneLite;

/**
 * The plugin's on-disk home (.runelite/bank-bis/) and shared file helpers.
 */
public final class PluginData
{

	public static final File DIR = new File(RuneLite.RUNELITE_DIR, "bank-bis");

	private PluginData()
	{
	}

	/**
	 * Writes via a unique temp file + rename so readers never observe a
	 * partial file, and concurrent writers cannot corrupt each other.
	 */
	public static void writeAtomically(File target, byte[] bytes) throws IOException
	{
		Files.createDirectories(target.toPath().getParent());
		Path tmp = Files.createTempFile(target.toPath().getParent(), target.getName(), ".tmp");
		try
		{
			Files.write(tmp, bytes);
			try
			{
				Files.move(tmp, target.toPath(), StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
			}
			catch (AtomicMoveNotSupportedException e)
			{
				Files.move(tmp, target.toPath(), StandardCopyOption.REPLACE_EXISTING);
			}
		}
		finally
		{
			Files.deleteIfExists(tmp);
		}
	}

}

package com.bankbis.data;

import com.duckblade.osrs.dpscalc.calc.model.DefenderAttributes;
import com.duckblade.osrs.dpscalc.calc.model.DefensiveBonuses;
import com.duckblade.osrs.dpscalc.calc.model.ItemStats;
import com.duckblade.osrs.dpscalc.calc.model.Skills;
import com.duckblade.osrs.dpscalc.calc.model.WeaponCategory;
import com.google.common.collect.ImmutableMap;
import java.util.Locale;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Skill;

/**
 * Maps wiki JSON entries onto the calc engine's model types.
 */
@Slf4j
public class WikiDataMapper
{

	private static final Map<String, EquipmentInventorySlot> SLOTS = ImmutableMap.<String, EquipmentInventorySlot>builder()
		.put("head", EquipmentInventorySlot.HEAD)
		.put("cape", EquipmentInventorySlot.CAPE)
		.put("neck", EquipmentInventorySlot.AMULET)
		.put("ammo", EquipmentInventorySlot.AMMO)
		.put("weapon", EquipmentInventorySlot.WEAPON)
		.put("body", EquipmentInventorySlot.BODY)
		.put("shield", EquipmentInventorySlot.SHIELD)
		.put("legs", EquipmentInventorySlot.LEGS)
		.put("hands", EquipmentInventorySlot.GLOVES)
		.put("feet", EquipmentInventorySlot.BOOTS)
		.put("ring", EquipmentInventorySlot.RING)
		.build();

	// categories the wiki added after the engine's WeaponCategory enum was written,
	// aliased to the closest style layout until proper support is added
	private static final Map<String, WeaponCategory> CATEGORY_ALIASES = ImmutableMap.of(
		"FLAIL", WeaponCategory.SPIKED,
		"MULTI_MELEE", WeaponCategory.CLAW,
		"GUN", WeaponCategory.UNARMED,
		"BLASTER", WeaponCategory.THROWN
	);

	public static EquipmentInventorySlot slotOf(EquipmentJson e)
	{
		return SLOTS.get(e.getSlot());
	}

	public static ItemStats toItemStats(EquipmentJson e)
	{
		EquipmentInventorySlot slot = slotOf(e);
		return ItemStats.builder()
			.itemId(e.getId())
			.name(e.getName())
			.accuracyStab(e.getOffensive().getStab())
			.accuracySlash(e.getOffensive().getSlash())
			.accuracyCrush(e.getOffensive().getCrush())
			.accuracyMagic(e.getOffensive().getMagic())
			.accuracyRanged(e.getOffensive().getRanged())
			.strengthMelee(e.getBonuses().getStr())
			.strengthRanged(e.getBonuses().getRangedStr())
			// wiki data stores magic damage in tenths of a percent; the engine expects whole percents
			.strengthMagic((int) Math.round(e.getBonuses().getMagicStr() / 10.0))
			.prayer(e.getBonuses().getPrayer())
			.speed(e.getSpeed() > 0 ? e.getSpeed() : 4)
			.slot(slot != null ? slot.getSlotIdx() : -1)
			.is2h(e.isTwoHanded())
			.weaponCategory(categoryOf(e))
			.build();
	}

	public static WeaponCategory categoryOf(EquipmentJson e)
	{
		String raw = e.getCategory();
		if (raw == null || raw.isEmpty())
		{
			return WeaponCategory.UNARMED;
		}

		String normalized = raw.toUpperCase(Locale.ROOT)
			.replace("2H SWORD", "TWO_HANDED_SWORD")
			.replace(' ', '_')
			.replace('-', '_');

		WeaponCategory alias = CATEGORY_ALIASES.get(normalized);
		if (alias != null)
		{
			return alias;
		}

		try
		{
			return WeaponCategory.valueOf(normalized);
		}
		catch (IllegalArgumentException ex)
		{
			log.debug("Unknown weapon category [{}] for item [{}], treating as unarmed", raw, e.getName());
			return WeaponCategory.UNARMED;
		}
	}

	public static Skills toNpcSkills(MonsterJson m)
	{
		return Skills.builder()
			.level(Skill.ATTACK, m.getSkills().getAtk())
			.level(Skill.STRENGTH, m.getSkills().getStr())
			.level(Skill.DEFENCE, m.getSkills().getDef())
			.level(Skill.MAGIC, m.getSkills().getMagic())
			.level(Skill.RANGED, m.getSkills().getRanged())
			.level(Skill.HITPOINTS, m.getSkills().getHp())
			.build();
	}

	public static DefensiveBonuses toDefensiveBonuses(MonsterJson m)
	{
		return DefensiveBonuses.builder()
			.defenseStab(m.getDefensive().getStab())
			.defenseSlash(m.getDefensive().getSlash())
			.defenseCrush(m.getDefensive().getCrush())
			.defenseMagic(m.getDefensive().getMagic())
			// split ranged defence: standard = bows, light = thrown, heavy = crossbows
			.defenseRanged(m.getDefensive().getStandard())
			.defenseRangedLight(m.getDefensive().getLight())
			.defenseRangedHeavy(m.getDefensive().getHeavy())
			.build();
	}

	public static DefenderAttributes toDefenderAttributes(MonsterJson m)
	{
		boolean demon = m.getAttributes().contains("demon");
		boolean dragon = m.getAttributes().contains("dragon");
		boolean kalphite = m.getAttributes().contains("kalphite");
		boolean leafy = m.getAttributes().contains("leafy");
		boolean undead = m.getAttributes().contains("undead");
		boolean fiery = m.getAttributes().contains("fiery");

		return DefenderAttributes.builder()
			.npcId(m.getId())
			.name(displayName(m))
			.isDemon(demon)
			.isDragon(dragon)
			.isKalphite(kalphite)
			.isLeafy(leafy)
			.isUndead(undead)
			.isFiery(fiery)
			.isVampyre1(m.getAttributes().contains("vampyre1"))
			.isVampyre2(m.getAttributes().contains("vampyre2"))
			.isVampyre3(m.getAttributes().contains("vampyre3"))
			.size(m.getSize())
			.accuracyMagic(m.getOffensive().getMagic())
			.elementalWeakness(m.getWeakness() == null || m.getWeakness().getElement() == null
				? null : m.getWeakness().getElement().toLowerCase(Locale.ROOT))
			.elementalWeaknessSeverity(m.getWeakness() == null ? 0 : m.getWeakness().getSeverity())
			.build();
	}

	public static String displayName(MonsterJson m)
	{
		if (m.getVersion() == null || m.getVersion().isEmpty())
		{
			return m.getName();
		}
		return m.getName() + " (" + m.getVersion() + ")";
	}

}

package com.bankbis.data;

import com.duckblade.osrs.dpscalc.calc.model.ItemStats;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.ByteArrayInputStream;
import java.io.File;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.Reader;
import java.util.ArrayList;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.time.Duration;
import java.time.Instant;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Loads equipment and monster data maintained by the OSRS Wiki team
 * (weirdgloop/osrs-dps-calc), with an on-disk cache under .runelite/bank-bis/.
 */
@Slf4j
@Singleton
public class WikiDataService
{

	private static final String BASE_URL = "https://raw.githubusercontent.com/weirdgloop/osrs-dps-calc/main/cdn/json/";
	private static final Duration CACHE_TTL = Duration.ofHours(24);

	private static final Type EQUIPMENT_TYPE = new TypeToken<List<EquipmentJson>>()
	{
	}.getType();
	private static final Type MONSTERS_TYPE = new TypeToken<List<MonsterJson>>()
	{
	}.getType();

	private final OkHttpClient okHttpClient;
	private final Gson gson;
	private final ScheduledExecutorService executor;
	private final File cacheDir;
	private final List<Call> inFlight = Collections.synchronizedList(new ArrayList<>());

	private CompletableFuture<Void> loadFuture;

	@Getter
	private volatile Map<Integer, ItemStats> itemStatsById = Collections.emptyMap();

	@Getter
	private volatile Map<Integer, NpcStats> npcStatsById = Collections.emptyMap();

	@Inject
	public WikiDataService(OkHttpClient okHttpClient, Gson gson, ScheduledExecutorService executor)
	{
		this(okHttpClient, gson, executor, PluginData.DIR);
	}

	WikiDataService(OkHttpClient okHttpClient, Gson gson, ScheduledExecutorService executor, File cacheDir)
	{
		this.executor = executor;
		this.okHttpClient = okHttpClient.newBuilder()
			.addInterceptor(chain -> chain.proceed(
				chain.request()
					.newBuilder()
					.header("User-Agent", "RuneLite plugin bank-bis")
					.build()))
			.build();
		this.gson = gson;
		this.cacheDir = cacheDir;
	}

	/**
	 * Loads both data files, from network if the disk cache is stale,
	 * falling back to the disk cache when the network is unavailable.
	 * Concurrent calls share one load. Never call on the client thread.
	 */
	public synchronized CompletableFuture<Void> load()
	{
		if (loadFuture != null && !loadFuture.isDone())
		{
			return loadFuture;
		}
		loadFuture = doLoad();
		return loadFuture;
	}

	/**
	 * Cancels any in-flight downloads. Call on plugin shutdown.
	 */
	public void shutdown()
	{
		synchronized (inFlight)
		{
			for (Call call : inFlight)
			{
				call.cancel();
			}
			inFlight.clear();
		}
	}

	private CompletableFuture<Void> doLoad()
	{
		CompletableFuture<Void> equipment = loadFile("equipment.json", EQUIPMENT_TYPE, (List<EquipmentJson> parsed) ->
		{
			Map<Integer, ItemStats> byId = new HashMap<>();
			for (EquipmentJson e : parsed)
			{
				byId.put(e.getId(), WikiDataMapper.toItemStats(e));
			}
			itemStatsById = Collections.unmodifiableMap(byId);
			log.debug("Loaded {} equipment entries", byId.size());
		});

		CompletableFuture<Void> monsters = loadFile("monsters.json", MONSTERS_TYPE, (List<MonsterJson> parsed) ->
		{
			Map<Integer, MonsterJson> chosen = new HashMap<>();
			for (MonsterJson m : parsed)
			{
				chosen.merge(m.getId(), m, WikiDataService::preferredVariant);
			}
			Map<Integer, NpcStats> byId = new HashMap<>();
			chosen.forEach((id, m) -> byId.put(id, NpcStats.of(m)));
			npcStatsById = Collections.unmodifiableMap(byId);
			log.debug("Loaded {} monster entries", byId.size());
		});

		return CompletableFuture.allOf(equipment, monsters);
	}

	/**
	 * Some monsters share one id across several stat variants (e.g. Duke
	 * Sucellus 12191 is listed as both Awakened and Post-quest). Prefer the
	 * everyday variant over Awakened/during-quest stats.
	 */
	static MonsterJson preferredVariant(MonsterJson a, MonsterJson b)
	{
		return variantScore(b) > variantScore(a) ? b : a;
	}

	private static int variantScore(MonsterJson m)
	{
		String version = m.getVersion() == null ? "" : m.getVersion().toLowerCase(Locale.ROOT);
		if (version.contains("awakened"))
		{
			return 0;
		}
		if (version.contains("quest") && !version.contains("post-quest"))
		{
			return 1;
		}
		return 2;
	}

	private <T> CompletableFuture<Void> loadFile(String fileName, Type type, Consumer<T> onParsed)
	{
		File cached = new File(cacheDir, fileName);
		CompletableFuture<Void> future = new CompletableFuture<>();
		// even the freshness stat() belongs off the caller's thread
		executor.execute(() ->
		{
			if (isFresh(cached))
			{
				try
				{
					parseFromDisk(cached, type, onParsed);
					future.complete(null);
					return;
				}
				catch (Exception e)
				{
					// fresh but unreadable (corrupt write, av interference):
					// fall through and self-heal from the network
					log.warn("Cached {} is unreadable, refetching", fileName, e);
				}
			}
			try
			{
				fetch(fileName, type, onParsed, cached, future);
			}
			catch (Exception e)
			{
				future.completeExceptionally(e);
			}
		});
		return future;
	}

	private <T> void fetch(String fileName, Type type, Consumer<T> onParsed, File cached, CompletableFuture<Void> future)
	{
		Request request = new Request.Builder().url(BASE_URL + fileName).build();
		Call call = okHttpClient.newCall(request);
		inFlight.add(call);
		call.enqueue(new Callback()
		{
			@Override
			public void onResponse(Call call, Response response)
			{
				inFlight.remove(call);
				try (ResponseBody body = response.body())
				{
					if (!response.isSuccessful() || body == null)
					{
						throw new IOException("Request for " + fileName + " failed: " + response);
					}
					byte[] bytes = body.bytes();
					T parsed = gson.fromJson(
						new InputStreamReader(new ByteArrayInputStream(bytes), StandardCharsets.UTF_8), type);
					onParsed.accept(parsed);
					writeCache(cached, bytes);
					future.complete(null);
				}
				catch (Exception e)
				{
					fallBackToDisk(e);
				}
			}

			@Override
			public void onFailure(Call call, IOException e)
			{
				inFlight.remove(call);
				fallBackToDisk(e);
			}

			private void fallBackToDisk(Exception cause)
			{
				if (cached.exists())
				{
					log.debug("Fetch of {} failed, using stale disk cache", fileName, cause);
					try
					{
						parseFromDisk(cached, type, onParsed);
						future.complete(null);
						return;
					}
					catch (Exception e)
					{
						cause = e;
					}
				}
				log.warn("Failed to load {}", fileName, cause);
				future.completeExceptionally(cause);
			}
		});
	}

	private <T> void parseFromDisk(File cached, Type type, Consumer<T> onParsed)
	{
		try (Reader reader = Files.newBufferedReader(cached.toPath(), StandardCharsets.UTF_8))
		{
			T parsed = gson.fromJson(reader, type);
			onParsed.accept(parsed);
		}
		catch (IOException e)
		{
			throw new RuntimeException("Failed to read cached " + cached.getName(), e);
		}
	}

	private void writeCache(File cached, byte[] bytes)
	{
		try
		{
			Files.createDirectories(cacheDir.toPath());
			Path tmp = cached.toPath().resolveSibling(cached.getName() + ".tmp");
			Files.write(tmp, bytes);
			Files.move(tmp, cached.toPath(), StandardCopyOption.REPLACE_EXISTING);
		}
		catch (IOException e)
		{
			log.warn("Failed to write cache file {}", cached, e);
		}
	}

	private boolean isFresh(File cached)
	{
		return cached.exists()
			&& Instant.ofEpochMilli(cached.lastModified()).plus(CACHE_TTL).isAfter(Instant.now());
	}

}

package com.bankbis.optimizer;

import com.duckblade.osrs.dpscalc.calc.model.AttackType;
import com.duckblade.osrs.dpscalc.calc.model.ItemStats;
import com.duckblade.osrs.dpscalc.calc.model.Prayer;
import com.google.common.collect.ImmutableSet;
import java.util.Set;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

@Getter
@RequiredArgsConstructor
public enum CombatClass
{

	MELEE(ImmutableSet.of(AttackType.STAB, AttackType.SLASH, AttackType.CRUSH)),
	RANGED(ImmutableSet.of(AttackType.RANGED)),
	MAGIC(ImmutableSet.of(AttackType.MAGIC)),
	;

	private final Set<AttackType> attackTypes;

	public boolean includes(AttackType type)
	{
		return attackTypes.contains(type);
	}

	public static CombatClass of(AttackType type)
	{
		for (CombatClass c : values())
		{
			if (c.includes(type))
			{
				return c;
			}
		}
		throw new IllegalArgumentException("No combat class for attack type " + type);
	}

	/**
	 * Best offensive prayers the player can actually activate at their
	 * prayer level. (Rigour/Augury unlock states are not detectable here;
	 * they are assumed unlocked at level - documented limitation.)
	 */
	public Set<Prayer> bestPrayers(int prayerLevel)
	{
		switch (this)
		{
			case MELEE:
				if (prayerLevel >= 70)
				{
					return ImmutableSet.of(Prayer.PIETY);
				}
				if (prayerLevel >= 60)
				{
					return ImmutableSet.of(Prayer.CHIVALRY);
				}
				if (prayerLevel >= 34)
				{
					return ImmutableSet.of(Prayer.ULTIMATE_STRENGTH, Prayer.INCREDIBLE_REFLEXES);
				}
				return ImmutableSet.of();

			case RANGED:
				if (prayerLevel >= 74)
				{
					return ImmutableSet.of(Prayer.RIGOUR);
				}
				if (prayerLevel >= 44)
				{
					return ImmutableSet.of(Prayer.EAGLE_EYE);
				}
				if (prayerLevel >= 26)
				{
					return ImmutableSet.of(Prayer.HAWK_EYE);
				}
				return ImmutableSet.of();

			case MAGIC:
			default:
				if (prayerLevel >= 77)
				{
					return ImmutableSet.of(Prayer.AUGURY);
				}
				if (prayerLevel >= 45)
				{
					return ImmutableSet.of(Prayer.MYSTIC_MIGHT);
				}
				if (prayerLevel >= 27)
				{
					return ImmutableSet.of(Prayer.MYSTIC_LORE);
				}
				return ImmutableSet.of();
		}
	}

	/**
	 * The stats the engine reads for this class, as a vector for dominance
	 * comparison. Order: accuracies..., strength, prayer.
	 */
	public int[] statsVector(ItemStats i)
	{
		switch (this)
		{
			case MELEE:
				return new int[]{i.getAccuracyStab(), i.getAccuracySlash(), i.getAccuracyCrush(), i.getStrengthMelee(), i.getPrayer()};
			case RANGED:
				return new int[]{i.getAccuracyRanged(), i.getStrengthRanged(), i.getPrayer()};
			case MAGIC:
			default:
				return new int[]{i.getAccuracyMagic(), i.getStrengthMagic(), i.getPrayer()};
		}
	}

	public int strengthOf(ItemStats i)
	{
		switch (this)
		{
			case MELEE:
				return i.getStrengthMelee();
			case RANGED:
				return i.getStrengthRanged();
			case MAGIC:
			default:
				return i.getStrengthMagic();
		}
	}

	public int accuracySumOf(ItemStats i)
	{
		switch (this)
		{
			case MELEE:
				return i.getAccuracyStab() + i.getAccuracySlash() + i.getAccuracyCrush();
			case RANGED:
				return i.getAccuracyRanged();
			case MAGIC:
			default:
				return i.getAccuracyMagic();
		}
	}

}

package com.bankbis.optimizer;

import com.duckblade.osrs.dpscalc.calc.model.AttackStyle;
import com.duckblade.osrs.dpscalc.calc.model.ItemStats;
import com.duckblade.osrs.dpscalc.calc.model.Spell;
import java.util.Map;
import lombok.Builder;
import lombok.Value;
import net.runelite.api.EquipmentInventorySlot;

/**
 * A concrete gear recommendation: what to wear, how to attack, and the
 * resulting DPS against the requested target.
 */
@Value
@Builder(toBuilder = true)
public class Loadout
{

	private final CombatClass combatClass;
	private final Map<EquipmentInventorySlot, ItemStats> items;
	private final AttackStyle attackStyle;

	/** The spell being cast, or null for non-casting loadouts. */
	private final Spell spell;

	private final double dps;

	/** Max hit and hit chance under the optimization assumptions, for
	 * display and comparison against the wiki calculator. */
	private final int maxHit;
	private final double accuracy;

	/**
	 * This same gear re-evaluated under fixed scenarios, for display.
	 * Null when the scenario evaluations failed.
	 */
	private final DpsBreakdown breakdown;

	@Value
	public static class DpsBreakdown
	{
		double base;
		double prayed;
		double potted;
	}

}

