package com.bankbis.optimizer;

import java.util.EnumMap;
import java.util.Map;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.Skill;

/**
 * Boost assumption for recommendations. CURRENT uses the player's live
 * boosted stats; the rest replace live boosts with the chosen potion's
 * effect computed from base levels, so you can plan a setup while standing
 * unpotted at the bank.
 */
@Getter
@RequiredArgsConstructor
public enum PotionBoost
{

	CURRENT("Current stats"),
	NONE("No boosts"),
	SUPER_SET("Super combat + ranging + heart"),
	OVERLOAD("Overload (raids)"),
	SMELLING_SALTS("Smelling salts"),
	;

	private final String label;

	/**
	 * @return boost deltas per skill, or null for CURRENT (keep live boosts)
	 */
	public Map<Skill, Integer> boostsFor(Map<Skill, Integer> levels)
	{
		Map<Skill, Integer> boosts = new EnumMap<>(Skill.class);
		switch (this)
		{
			case CURRENT:
				return null;

			case NONE:
				return boosts;

			case SUPER_SET:
				// super combat: +5 + 15%; ranging potion / saturated heart: +4 + 10%
				put(boosts, levels, Skill.ATTACK, 5, 0.15);
				put(boosts, levels, Skill.STRENGTH, 5, 0.15);
				put(boosts, levels, Skill.DEFENCE, 5, 0.15);
				put(boosts, levels, Skill.RANGED, 4, 0.10);
				put(boosts, levels, Skill.MAGIC, 4, 0.10);
				return boosts;

			case OVERLOAD:
				put(boosts, levels, Skill.ATTACK, 6, 0.16);
				put(boosts, levels, Skill.STRENGTH, 6, 0.16);
				put(boosts, levels, Skill.DEFENCE, 6, 0.16);
				put(boosts, levels, Skill.RANGED, 6, 0.16);
				put(boosts, levels, Skill.MAGIC, 6, 0.16);
				return boosts;

			case SMELLING_SALTS:
			default:
				put(boosts, levels, Skill.ATTACK, 11, 0.16);
				put(boosts, levels, Skill.STRENGTH, 11, 0.16);
				put(boosts, levels, Skill.DEFENCE, 11, 0.16);
				put(boosts, levels, Skill.RANGED, 11, 0.16);
				put(boosts, levels, Skill.MAGIC, 11, 0.16);
				return boosts;
		}
	}

	private static void put(Map<Skill, Integer> boosts, Map<Skill, Integer> levels, Skill skill, int base, double percent)
	{
		int level = levels.getOrDefault(skill, 1);
		boosts.put(skill, base + (int) (percent * level));
	}

	@Override
	public String toString()
	{
		return label;
	}

}

package com.bankbis.optimizer;

import com.duckblade.osrs.dpscalc.calc.model.Prayer;
import com.google.common.collect.ImmutableSet;
import java.util.Set;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * Which offensive prayers recommendations may assume. AUTO uses the best
 * prayer the player's level allows among prayers they have actually
 * unlocked (detected from varbits). NO_UNLOCKS forces the freely-available
 * tier regardless; NONE disables prayers entirely.
 */
@Getter
@RequiredArgsConstructor
public enum PrayerAssumption
{

	AUTO("Best unlocked"),
	NO_UNLOCKS("Basic prayers only"),
	NONE("No prayers"),
	;

	// caps just below the unlockable tiers: Chivalry/Piety (60/70),
	// Rigour (74), Augury (77)
	private static final int MELEE_BASIC_CAP = 59;
	private static final int RANGED_BASIC_CAP = 73;
	private static final int MAGIC_BASIC_CAP = 76;

	private final String label;

	public Set<Prayer> prayersFor(CombatClass combatClass, int prayerLevel, PrayerUnlocks unlocks)
	{
		switch (this)
		{
			case NONE:
				return ImmutableSet.of();

			case NO_UNLOCKS:
				return combatClass.bestPrayers(Math.min(prayerLevel, basicCap(combatClass)));

			case AUTO:
			default:
				boolean unlocked = combatClass == CombatClass.MELEE ? unlocks.isPietyChivalry()
					: combatClass == CombatClass.RANGED ? unlocks.isRigour() : unlocks.isAugury();
				int cap = unlocked ? Integer.MAX_VALUE : basicCap(combatClass);
				return combatClass.bestPrayers(Math.min(prayerLevel, cap));
		}
	}

	private static int basicCap(CombatClass combatClass)
	{
		return combatClass == CombatClass.MELEE ? MELEE_BASIC_CAP
			: combatClass == CombatClass.RANGED ? RANGED_BASIC_CAP : MAGIC_BASIC_CAP;
	}

	@Override
	public String toString()
	{
		return label;
	}

}

