package com.bankbis.content;

import com.bankbis.data.NpcStats;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

class MonsterSearchIndexTest
{

	private MonsterSearchIndex index;

	@BeforeEach
	void setUp()
	{
		Map<Integer, NpcStats> stats = new LinkedHashMap<>();
		stats.put(2042, npc("Zulrah (Serpentine)"));
		stats.put(2043, npc("Zulrah (Magma)"));
		stats.put(494, npc("Kraken"));
		stats.put(3021, npc("Man"));
		stats.put(3022, npc("Woman"));
		stats.put(6766, npc("Lizardman shaman"));
		stats.put(8059, npc("Vorkath"));
		index = new MonsterSearchIndex();
		index.build(stats);
	}

	private static NpcStats npc(String name)
	{
		return NpcStats.builder().displayName(name).build();
	}

	@Test
	void exactMatchResolvesCaseInsensitively()
	{
		MonsterSearchIndex.Resolution r = index.resolve("KRAKEN");
		assertTrue(r.isMatch());
		assertEquals(494, (int) r.getNpcId());
		assertEquals("Kraken", r.getDisplayName());
	}

	@Test
	void exactMatchWinsEvenWhenOthersContainIt()
	{
		// "man" is contained in Woman, Lizardman shaman - exact must win
		MonsterSearchIndex.Resolution r = index.resolve("man");
		assertTrue(r.isMatch());
		assertEquals(3021, (int) r.getNpcId());
	}

	@Test
	void uniqueSubstringResolves()
	{
		MonsterSearchIndex.Resolution r = index.resolve("vork");
		assertTrue(r.isMatch());
		assertEquals(8059, (int) r.getNpcId());
	}

	@Test
	void multipleMatchesAreAmbiguous()
	{
		MonsterSearchIndex.Resolution r = index.resolve("zulrah");
		assertFalse(r.isMatch());
		assertTrue(r.isAmbiguous());
	}

	@Test
	void noMatchesIsNone()
	{
		MonsterSearchIndex.Resolution r = index.resolve("tzkal-zuk");
		assertFalse(r.isMatch());
		assertFalse(r.isAmbiguous());
	}

	@Test
	void suggestionsRankPrefixBeforeContains()
	{
		List<String> suggestions = index.suggest("man", 10);
		assertEquals("Man", suggestions.get(0)); // prefix match first
		assertTrue(suggestions.contains("Woman"));
		assertTrue(suggestions.contains("Lizardman shaman"));
	}

	@Test
	void suggestionsRespectLimit()
	{
		assertEquals(1, index.suggest("man", 1).size());
	}

	@Test
	void exactPickerNameResolvesToDisplay()
	{
		assertEquals("Kraken", index.displayForName("kraken"));
		// live NPC named "Zulrah" prefix-matches one of the variant entries
		String zulrah = index.displayForName("Zulrah");
		assertTrue(zulrah != null && zulrah.startsWith("Zulrah ("));
		assertNull(index.displayForName("Nonexistent"));
	}

	@Test
	void emptyIndexResolvesNothing()
	{
		MonsterSearchIndex empty = new MonsterSearchIndex();
		assertTrue(empty.isEmpty());
		assertFalse(empty.resolve("kraken").isMatch());
		assertTrue(empty.suggest("kraken", 10).isEmpty());
	}

}

package com.bankbis.content;

import com.bankbis.data.NpcStats;
import com.duckblade.osrs.dpscalc.calc.model.Skills;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.Skill;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;
import org.junit.jupiter.api.Test;

class RaidScalingTest
{

	private static NpcStats npc(int def, int magic)
	{
		Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
		levels.put(Skill.DEFENCE, def);
		levels.put(Skill.MAGIC, magic);
		levels.put(Skill.HITPOINTS, 800);
		return NpcStats.builder()
			.displayName("Test monster")
			.speed(4)
			.skills(Skills.builder().levels(levels).build())
			.build();
	}

	private static Target coxTarget(int npcId, int partySize, boolean cm)
	{
		return Target.builder()
			.npcId(npcId)
			.label("Test")
			.raid(RaidType.COX)
			.raidPartySize(partySize)
			.coxChallengeMode(cm)
			.build();
	}

	@Test
	void nonRaidAndSoloNormalModeUnchanged()
	{
		NpcStats stats = npc(200, 200);
		assertSame(stats, RaidScaling.scale(stats, Target.builder().npcId(1).label("x").build()));
		assertSame(stats, RaidScaling.scale(stats, coxTarget(7551, 1, false)));
	}

	@Test
	void coxFiveManScalesDefenceAndMagic()
	{
		// party 5: m1=4 -> defensive pct = 100 + isqrt(4) + 4*7/10 = 104,
		// offensive pct = 100 + isqrt(4)*7 + 4 = 118 (magic offensive for Olm head)
		NpcStats scaled = RaidScaling.scale(npc(200, 200), coxTarget(7551, 5, false));
		assertEquals(208, (int) scaled.getSkills().getLevels().get(Skill.DEFENCE));
		assertEquals(236, (int) scaled.getSkills().getLevels().get(Skill.MAGIC));
	}

	@Test
	void coxMagicDefensiveMonsterUsesDefensivePct()
	{
		// Olm mage hand (7552): magic scales with the defensive pct
		NpcStats scaled = RaidScaling.scale(npc(200, 200), coxTarget(7552, 5, false));
		assertEquals(208, (int) scaled.getSkills().getLevels().get(Skill.MAGIC));
	}

	@Test
	void challengeModeAddsFiftyPercentDefence()
	{
		NpcStats scaled = RaidScaling.scale(npc(200, 200), coxTarget(7551, 1, true));
		assertEquals(300, (int) scaled.getSkills().getLevels().get(Skill.DEFENCE));
	}

	@Test
	void tektonChallengeModeUsesReducedPct()
	{
		// party 5: defensive pct 104 -> 208; Tekton CM at party >= 4 is
		// +35% -> 280. Magic is defensive for Tekton, same path.
		NpcStats scaled = RaidScaling.scale(npc(200, 200), coxTarget(7540, 5, true));
		assertEquals(280, (int) scaled.getSkills().getLevels().get(Skill.DEFENCE));
		assertEquals(280, (int) scaled.getSkills().getLevels().get(Skill.MAGIC));
	}

	@Test
	void toaDoesNotScaleStats()
	{
		NpcStats stats = npc(80, 100);
		NpcStats scaled = RaidScaling.scale(stats, Target.builder()
			.npcId(11730).label("Zebak").raid(RaidType.TOA).toaInvocationLevel(500).raidPartySize(8).build());
		assertSame(stats, scaled);
	}

}

package com.bankbis.content;

import com.bankbis.data.EquipmentJson;
import com.bankbis.data.MonsterJson;
import com.bankbis.data.NpcStats;
import com.bankbis.data.WikiDataMapper;
import com.bankbis.optimizer.Loadout;
import com.bankbis.optimizer.LoadoutOptimizer;
import com.bankbis.optimizer.OptimizeRequest;
import com.bankbis.testutil.TestFixtures;
import com.duckblade.osrs.dpscalc.calc.DpsComputeModule;
import com.duckblade.osrs.dpscalc.calc.model.ItemStats;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.google.inject.Guice;
import java.io.Reader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.EquipmentInventorySlot;
import org.junit.jupiter.api.Assumptions;
import org.junit.jupiter.api.Test;

/**
 * Local-only pre-flight sweep: runs every ContentPreset against the real
 * on-disk bank snapshot and live wiki data cache. Not committed to CI -
 * depends on local .runelite state.
 */
class RealBankPresetSweep
{

	private static final Path RUNELITE_DATA = Paths.get(System.getProperty("user.home"), ".runelite", "bank-bis");

	@Test
	void sweepAllPresetsAgainstRealBank() throws Exception
	{
		Assumptions.assumeTrue(Files.exists(RUNELITE_DATA.resolve("equipment.json")),
			"no local wiki data cache; sweep only runs on a machine that has used the plugin");

		Gson gson = new Gson();
		Type eqType = new TypeToken<List<EquipmentJson>>()
		{
		}.getType();
		Type monType = new TypeToken<List<MonsterJson>>()
		{
		}.getType();
		Type ownedType = new TypeToken<Map<String, Map<Integer, Integer>>>()
		{
		}.getType();

		Map<Integer, ItemStats> wikiItems = new HashMap<>();
		try (Reader r = Files.newBufferedReader(RUNELITE_DATA.resolve("equipment.json"), StandardCharsets.UTF_8))
		{
			List<EquipmentJson> parsed = gson.fromJson(r, eqType);
			for (EquipmentJson e : parsed)
			{
				wikiItems.put(e.getId(), WikiDataMapper.toItemStats(e));
			}
		}

		Map<Integer, MonsterJson> monsters = new HashMap<>();
		try (Reader r = Files.newBufferedReader(RUNELITE_DATA.resolve("monsters.json"), StandardCharsets.UTF_8))
		{
			List<MonsterJson> parsed = gson.fromJson(r, monType);
			for (MonsterJson m : parsed)
			{
				monsters.merge(m.getId(), m, (a, b) -> a); // sweep: first variant is fine
			}
		}

		Path owned = Files.list(RUNELITE_DATA)
			.filter(p -> p.getFileName().toString().startsWith("owned-"))
			.findFirst()
			.orElse(null);
		Assumptions.assumeTrue(owned != null, "no owned-items snapshot; open the bank in-game once first");
		Map<String, Map<Integer, Integer>> sources;
		try (Reader r = Files.newBufferedReader(owned, StandardCharsets.UTF_8))
		{
			sources = gson.fromJson(r, ownedType);
		}
		Map<Integer, Integer> quantities = new HashMap<>();
		sources.values().forEach(m -> m.forEach((id, q) -> quantities.merge(id, q, Integer::sum)));

		List<ItemStats> ownedEquipment = new ArrayList<>();
		quantities.keySet().forEach(id ->
		{
			ItemStats stats = wikiItems.get(id);
			if (stats != null)
			{
				ownedEquipment.add(stats);
			}
		});

		System.out.printf("bank snapshot: %d items, %d equippable%n", quantities.size(), ownedEquipment.size());

		LoadoutOptimizer optimizer = Guice.createInjector(new DpsComputeModule()).getInstance(LoadoutOptimizer.class);
		int failures = 0;
		for (ContentPreset preset : ContentPreset.values())
		{
			MonsterJson monster = monsters.get(preset.getPrimaryMonsterId());
			if (monster == null)
			{
				System.out.printf("%-35s MISSING MONSTER id=%d%n", preset.getLabel(), preset.getPrimaryMonsterId());
				failures++;
				continue;
			}

			long start = System.nanoTime();
			List<Loadout> loadouts;
			try
			{
				loadouts = optimizer.optimize(OptimizeRequest.builder()
					.ownedEquipment(ownedEquipment)
					.playerSkills(TestFixtures.maxedWithBoosts())
					.target(NpcStats.of(monster))
					.onSlayerTask(preset.isOnSlayerTask())
					.raidPartySize(preset.getRaidPartySize())
					.build());
			}
			catch (Exception e)
			{
				System.out.printf("%-35s THREW %s%n", preset.getLabel(), e);
				failures++;
				continue;
			}
			long ms = (System.nanoTime() - start) / 1_000_000;

			if (loadouts.isEmpty())
			{
				System.out.printf("%-35s NO LOADOUTS (%d ms)%n", preset.getLabel(), ms);
				failures++;
				continue;
			}

			StringBuilder sb = new StringBuilder();
			for (Loadout l : loadouts)
			{
				if (l.getDps() > 40 || !Double.isFinite(l.getDps()))
				{
					sb.append(" [SUSPICIOUS DPS]");
					failures++;
				}
				sb.append(String.format(" %s=%.2f(%s)", l.getCombatClass(), l.getDps(),
					l.getItems().get(EquipmentInventorySlot.WEAPON).getName()));
			}
			System.out.printf("%-35s %4dms%s%n", preset.getLabel(), ms, sb);
		}

		System.out.println("failures: " + failures);
		if (failures > 0)
		{
			throw new AssertionError(failures + " preset(s) failed the sweep");
		}
	}

}

