		List<ItemStats> gear = bank("Rune crossbow", "Broad bolts", "Slayer helmet (i)", "Black mask");

		Loadout onTask = loadoutFor(optimizer.optimize(request(gear, ABYSSAL_DEMON, true)), CombatClass.RANGED)
