	{
		when(context.get(ComputeInputs.DEFENDER_ATTRIBUTES)).thenReturn(UNDEAD);
		when(context.get(ComputeInputs.ATTACK_STYLE)).thenReturn(ofAttackType(AttackType.MAGIC));
